/** Research design vocabulary. Clinical wire types remain generated by Lean. */
export const dimensions = {
  navigation: ['list', 'tabs', 'timeline', 'spatial', 'command', 'conversational'],
  layout: ['stack', 'columns', 'document', 'timeline', 'spatial', 'board'],
  input: ['mouse', 'keyboard', 'voice'],
  alertChannel: ['spec', 'persistent-rail', 'audio'],
  density: ['normal', 'compact'],
  patientScope: ['single', 'multi'],
  temporalView: ['encounter', 'longitudinal', 'aligned'],
} as const;
export type Dimensions = { [K in keyof typeof dimensions]: (typeof dimensions)[K][number] };
export type Tier = 'proved' | 'checked' | 'sandbox';
export type Workflow = `W${1 | 2 | 3 | 4 | 5 | 6 | 7}`;
export type TaskExpr = { op: 'atom'; id: string } |
  { op: 'seq' | 'parallel' | 'choice'; tasks: TaskExpr[] } |
  { op: 'optional' | 'repeat'; task: TaskExpr };
export interface DesignPoint extends Dimensions {
  tier: Tier;
  /** Overrides map named task groups to a different admitted layout. */
  taskLayouts: Record<string, Dimensions['layout']>;
}
export const defaultPoint: DesignPoint = {
  tier: 'proved', navigation: 'list', layout: 'stack', input: 'mouse',
  alertChannel: 'spec', density: 'normal', patientScope: 'single',
  temporalView: 'encounter', taskLayouts: {},
};
export function parsePoint(value: unknown): DesignPoint {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw Error('Expected design object');
  const obj = value as Record<string, unknown>;
  const keys = [...Object.keys(dimensions), 'tier', 'taskLayouts'];
  if (Object.keys(obj).some(k => !keys.includes(k))) throw Error('Unknown design dimension');
  for (const [key, values] of Object.entries(dimensions)) {
    if (!(values as readonly unknown[]).includes(obj[key])) throw Error(`Invalid ${key}`);
  }
  if (!['proved', 'checked', 'sandbox'].includes(String(obj['tier']))) throw Error('Invalid tier');
  const overrides = obj['taskLayouts'];
  if (!overrides || typeof overrides !== 'object' || Array.isArray(overrides) ||
    Object.values(overrides).some(v => !dimensions.layout.includes(v as Dimensions['layout']))) throw Error('Invalid task layouts');
  return structuredClone(obj) as unknown as DesignPoint;
}
export function unsupported(p: DesignPoint): string[] {
  return [
    ...(!['list', 'timeline'].includes(p.navigation) ? [`navigation:${p.navigation}`] : []),
    ...([p.layout, ...Object.values(p.taskLayouts)].filter(x => !['stack','columns','document','timeline'].includes(x)).map(x => `layout:${x}`)),
    ...(p.navigation === 'timeline' && p.layout !== 'timeline' ? ['timeline navigation requires timeline layout'] : []),
    ...(p.input === 'voice' ? ['input:voice'] : []),
    ...(p.alertChannel !== 'spec' ? [`alertChannel:${p.alertChannel}`] : []),
    ...(p.patientScope !== 'single' ? ['patientScope:multi'] : []),
    ...(p.temporalView === 'aligned' ? ['temporalView:aligned'] : []),
  ];
}
export function niche(p: DesignPoint): string {
  return [p.tier, ...Object.keys(dimensions).map(k => p[k as keyof Dimensions])].join('/');
}
/** Stable one-hot features: no arbitrary ordinal distance between paradigms. */
export function features(p: DesignPoint): number[] {
  return Object.entries(dimensions).flatMap(([k, values]) => values.map(v => Number(p[k as keyof Dimensions] === v)));
}
export function seedPoints(): DesignPoint[] {
  return (['stack','columns','document','timeline'] as const).map(layout => ({ ...defaultPoint, layout, taskLayouts: {},
    temporalView: layout === 'timeline' ? 'longitudinal' : 'encounter' }));
}
